#include <stdio.h>
#include <signal.h>

static volatile sig_atomic_t n = 0;

static void handler(int sig)
{
    (void)sig;
    n++;
}

int main(void)
{
    int i;

    signal(SIGUSR1, handler);
    for (i = 0; i < 3; i++)
        raise(SIGUSR1);
    printf("%d\n", (int)n);
    return 0;
}
